const data = $input.first().json;

// كل رسائل المحادثة
const messages = Array.isArray(data.messages)
  ? data.messages
  : [];

// نأخذ فقط الرسائل التي كتبها العميل
const customerMessages = messages.filter(message =>
  message.actor_type === 'user' &&
  message.created_time
);

// إذا لم نجد أي رسالة من العميل
if (customerMessages.length === 0) {
  return [
    {
      json: {
        last_customer_message: null,
        last_customer_message_time: null,
        hours_since_customer_message: null,
        within_24h: false,
        reason: 'no_customer_message_found'
      }
    }
  ];
}

// ترتيب رسائل العميل من الأحدث إلى الأقدم
customerMessages.sort((a, b) =>
  new Date(b.created_time).getTime() -
  new Date(a.created_time).getTime()
);

// أحدث رسالة من العميل
const lastCustomerMessage = customerMessages[0];

// استخراج نص الرسالة
const lastCustomerMessageText = (lastCustomerMessage.message_parts || [])
  .map(part => part?.text?.content)
  .filter(Boolean)
  .join('\n');

// حساب كم ساعة مرت
const lastMessageTime = new Date(lastCustomerMessage.created_time).getTime();
const now = Date.now();

const hoursSinceCustomerMessage =
  (now - lastMessageTime) / (1000 * 60 * 60);

// هل ما زلنا داخل نافذة الـ 24 ساعة؟
const within24h = hoursSinceCustomerMessage < 24;

return [
  {
    json: {
      last_customer_message: lastCustomerMessageText || null,
      last_customer_message_time: lastCustomerMessage.created_time,

      hours_since_customer_message:
        Number(hoursSinceCustomerMessage.toFixed(2)),

      within_24h: within24h,

      last_customer_message_id: lastCustomerMessage.id || null
    }
  }
];

